-- Remove lighting map controls and the submission requirement at the user's request.
-- Existing saved data, evidence requirements and access boundaries are retained.
CREATE OR REPLACE FUNCTION private.entergy_form_definition(p_kind text) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path='' AS $fn$ SELECT $definition${"cleanup":{"title":"Clean-up form","source":"Entergy Clean-up Form.pdf","sourceUrl":"/forms/entergy/clean-up.pdf","revision":null,"sections":[{"id":"cleanup","title":"Cleanup scope","description":"Describe environmental work and every material type and amount.","fields":[{"key":"environmentalCleanup","label":"Environmental cleanup","kind":"notes","required":true},{"key":"trashCleanup","label":"Trash cleanup (material type & amount)","kind":"notes","required":true}]},{"id":"location","title":"Site & access","description":"Keep the site identifiable for the Entergy crew lead.","fields":[{"key":"address","label":"Address","kind":"text","required":true},{"key":"cityTown","label":"City/Town","kind":"text","required":true},{"key":"dloc","label":"DLOC","kind":"text","required":true},{"key":"truckAccess","label":"Truck access","kind":"boolean","required":true}]},{"id":"notes","title":"Field notes","description":"Record access restrictions, disposal details, or other observations.","fields":[{"key":"notes","label":"Notes","kind":"notes","required":true}]}]},"damage":{"title":"Damage assessment","source":"Entergy Distribution Change Order.pdf","sourceUrl":"/forms/entergy/distribution-change-order.pdf","revision":"02-25-2019","sections":[{"id":"scope","title":"Equipment & activity","description":"Select every equipment type and activity covered by this change order.","fields":[{"key":"date","label":"Date","kind":"date","required":true},{"key":"equipmentTypes","label":"Equipment type","kind":"multi","options":["Transformer","Recloser","Regulator","Switch","Switch Gear","Pole","AutoTransformer","Streetlight","Capacitor","Breaker","Sectionalizer","Fault Indicator","Communication Device","Private Area Light"],"required":true},{"key":"activities","label":"Activity","kind":"multi","options":["Install","Relocate","Remove","Install/Remove","Other","Misc."],"required":true}]},{"id":"location","title":"From / to location","description":"Preserve location numbers as written, including leading zeros.","fields":[{"key":"fromLocalOffice","label":"From \u00b7 Local office","kind":"text"},{"key":"fromStoreRoom","label":"From \u00b7 Store room","kind":"text"},{"key":"fromDloc","label":"From \u00b7 Distribution location number (DLOC)","kind":"text"},{"key":"toLocalOffice","label":"To \u00b7 Local office","kind":"text"},{"key":"toStoreRoom","label":"To \u00b7 Store room","kind":"text"},{"key":"toDloc","label":"To \u00b7 Distribution location number (DLOC)","kind":"text"},{"key":"latitude","label":"GPS \u00b7 LAT","kind":"latitude"},{"key":"longitude","label":"GPS \u00b7 LONG","kind":"longitude"}]},{"id":"equipment","title":"Equipment register","description":"Three install/remove pairs on the paper form. Add rows when the site needs more.","fields":[{"key":"operation","label":"Install / remove","kind":"select","options":["Install","Remove"]},{"key":"type","label":"Type","kind":"text"},{"key":"size","label":"Size","kind":"text"},{"key":"companyEquipmentNumber","label":"Company equipment number","kind":"text"},{"key":"manufacturerSerialNumber","label":"Manufacturer serial number","kind":"text"},{"key":"phases","label":"Phase","kind":"multi","options":["A","B","C"]},{"key":"fieldPhase","label":"Field phase","kind":"select","options":["F","M","R","T","C","B"]},{"key":"counterReading","label":"Rec/Reg/Cap counter reading","kind":"text"}],"repeat":{"key":"equipmentRows","minimumRows":6}},{"id":"transformer","title":"Transformer & feeder","description":"Installation purpose, voltage, inspection disposition and bank connection.","fields":[{"key":"phaseChange","label":"Phase \u00b7 Change","kind":"boolean"},{"key":"transformerPurpose","label":"Transformer installation purpose","kind":"multi","options":["Change","Metered Customer","UnMetered Customer","Lighting","Behind Primary Meter","Company Line","Company Substation"]},{"key":"primaryVoltage","label":"Voltage \u00b7 Pri.","kind":"text"},{"key":"secondaryVoltage","label":"Voltage \u00b7 Sec.","kind":"text"},{"key":"idleTransformerInspection","label":"Idle transformer inspection","kind":"multi","options":["Reuse","Rebuild","Scrap","Spare","Inactive"]},{"key":"bankConnection","label":"Transformer bank secondary connection","kind":"multi","options":["Wye","Delta"]},{"key":"feederNumber","label":"Feeder no.","kind":"text"},{"key":"feederChange","label":"Feeder \u00b7 Change","kind":"boolean"}]},{"id":"lighting","title":"Lighting","description":"Record street light and private area light wattage and type.","fields":[{"key":"streetLightWattage","label":"Street light \u00b7 Wattage","kind":"text"},{"key":"streetLightType","label":"Street light \u00b7 Type","kind":"text"},{"key":"privateAreaLightWattage","label":"Private area light \u00b7 Wattage","kind":"text"},{"key":"privateAreaLightType","label":"Private area light \u00b7 Type","kind":"text"}]},{"id":"customerSite","title":"Customer & field address","description":"Customer and location/comments lines from the source.","fields":[{"key":"customer","label":"Customer","kind":"text"},{"key":"fieldAddressComments","label":"Field address/comments","kind":"notes","required":true}]},{"id":"switch","title":"Disconnect / lateral / bypass switch / switch gear / status","description":"Keep equipment identifiers, switch status and bypass details together.","fields":[{"key":"switchTypes","label":"Switch type","kind":"multi","options":["Disconnect","GOAB","Fuse","Switch Gear"]},{"key":"installedNumber","label":"Installed #","kind":"text"},{"key":"removedNumber","label":"Removed #","kind":"text"},{"key":"switchQuantity","label":"Quantity","kind":"text"},{"key":"switchSize","label":"Switch size","kind":"text"},{"key":"switchType","label":"Switch type (specification)","kind":"text"},{"key":"changeStatus","label":"Change status","kind":"multi","options":["New","Replace","Change"]},{"key":"switchPosition","label":"Switch position","kind":"multi","options":["Open","Closed","Bypass"]},{"key":"switchManufacturerNumber","label":"Switch manufacturer #","kind":"text"},{"key":"catalogNumber","label":"Catalog #","kind":"text"},{"key":"manufacturerSerialNumber","label":"Manufacturer serial #","kind":"text"},{"key":"manufacturerDate","label":"Manufacturer date","kind":"date"},{"key":"bypassSwitchTypes","label":"Bypass switch type","kind":"multi","options":["Disconnect","Fuse","Solid Blade","GOAB","Fuse Around","Other"]},{"key":"bypassSize","label":"Bypass size","kind":"text"},{"key":"bypassType","label":"Bypass type (specification)","kind":"text"}]},{"id":"pole","title":"Pole change out","description":"Record installed and removed size/class and pole ownership.","fields":[{"key":"poleInstallSizeClass","label":"Install size/class","kind":"text"},{"key":"poleRemoveSizeClass","label":"Remove size/class","kind":"text"},{"key":"poleOwners","label":"Owner","kind":"multi","options":["Company","ATT","Other"]},{"key":"poleOtherOwner","label":"Other owner","kind":"text"}]},{"id":"communication","title":"Communication devices","description":"Communication equipment, battery, antenna location and reason for change.","fields":[{"key":"communicationDeviceTypes","label":"Type of comm device","kind":"multi","options":["Access Point (AP)","Relay (RY)"]},{"key":"commEquipmentNumber","label":"COMM equipment #","kind":"text"},{"key":"commSerialNumber","label":"COMM serial #","kind":"text"},{"key":"commBatteryEquipmentNumber","label":"Battery equipment #","kind":"text"},{"key":"commBatterySerialNumber","label":"Battery serial #","kind":"text"},{"key":"antennaLocations","label":"Antenna location","kind":"multi","options":["w/COMM","Other Location"]},{"key":"commReasons","label":"Reason for change","kind":"multi","options":["PID","Replacement","New Installation"]}]},{"id":"controls","title":"Controls","description":"Select the equipment type at the top of the form.","fields":[{"key":"controlEquipmentNumber","label":"Control equipment #","kind":"text"},{"key":"controlSerialNumber","label":"Control serial #","kind":"text"},{"key":"commBridgeEquipmentNumber","label":"COMM bridge equipment #","kind":"text"},{"key":"commBridgeSerialNumber","label":"COMM bridge serial #","kind":"text"},{"key":"battery1EquipmentNumber","label":"Battery 1 equipment #","kind":"text"},{"key":"battery1SerialNumber","label":"Battery 1 serial #","kind":"text"},{"key":"battery2EquipmentNumber","label":"Battery 2 equipment #","kind":"text"},{"key":"battery2SerialNumber","label":"Battery 2 serial #","kind":"text"},{"key":"controlReasons","label":"Reason for change","kind":"multi","options":["PID","Replacement","New Installation"]}]},{"id":"transfers","title":"Customer transfers","description":"Accounts moved to a new DLOC/transformer. The paper includes three rows.","fields":[{"key":"customerNameAddress","label":"Customer name or address","kind":"text"},{"key":"identifierTypes","label":"Identifier type","kind":"multi","options":["Account #","Meter #","Net Metering #"]},{"key":"identifier","label":"Account / meter / net metering number","kind":"text"},{"key":"oldDlocTransformer","label":"Old DLOC or trans. #","kind":"text"},{"key":"newDlocTransformer","label":"New DLOC or trans. #","kind":"text"}],"repeat":{"key":"customerRows","minimumRows":3}},{"id":"signoff","title":"Sign-off","description":"Keep the printed work order and employee identifiers. Typed signature records the entered name.","fields":[{"key":"signature","label":"Signature","kind":"text","required":true},{"key":"workOrderNumber","label":"Work order #","kind":"text","required":true},{"key":"employeeId","label":"Employee ID","kind":"text","required":true}]}]}}$definition$::jsonb->p_kind; $fn$;

CREATE OR REPLACE FUNCTION private.assert_entergy_payload(p_kind text,p_payload jsonb,p_submit boolean) RETURNS void
LANGUAGE plpgsql SET search_path='' AS $$
DECLARE definition jsonb:=private.entergy_form_definition(p_kind); section jsonb; field jsonb; row_value jsonb; stroke jsonb; point jsonb; fields jsonb; answers jsonb; row_key text; unknown_key text; required_key text; damage_detail jsonb;
BEGIN
 IF definition IS NULL OR jsonb_typeof(p_payload)<>'object' OR p_payload->'version' IS DISTINCT FROM '1'::jsonb OR jsonb_typeof(p_payload->'answers') IS DISTINCT FROM 'object' OR jsonb_typeof(p_payload->'equipmentRows') IS DISTINCT FROM 'array' OR jsonb_typeof(p_payload->'customerRows') IS DISTINCT FROM 'array' OR jsonb_typeof(p_payload->'lightingMap') IS DISTINCT FROM 'array' OR jsonb_typeof(p_payload->'damageReports') IS DISTINCT FROM 'object' OR octet_length(p_payload::text)>2000000 THEN RAISE EXCEPTION 'Invalid Entergy form structure' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_payload) k WHERE k NOT IN ('version','answers','equipmentRows','customerRows','lightingMap','damageReports')) THEN RAISE EXCEPTION 'Unknown form property' USING ERRCODE='23514'; END IF;
 SELECT jsonb_agg(f) INTO fields FROM jsonb_array_elements(definition->'sections') s,jsonb_array_elements(s->'fields') f WHERE NOT(s ? 'repeat');
 -- Retain compatibility with saved drafts from before map controls were removed.
 IF p_kind='damage' THEN fields:=fields||jsonb_build_array(jsonb_build_object('key','lightingMapNotes','label','Saved lighting legend','kind','notes')); END IF;
 answers:=p_payload->'answers';
 FOR unknown_key IN SELECT jsonb_object_keys(answers) LOOP
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(fields) f WHERE f->>'key'=unknown_key) THEN RAISE EXCEPTION 'Unknown form field: %',unknown_key USING ERRCODE='23514'; END IF;
 END LOOP;
 FOR field IN SELECT value FROM jsonb_array_elements(fields) LOOP PERFORM private.assert_entergy_field(field,answers->(field->>'key'),p_submit); END LOOP;
 FOR section IN SELECT value FROM jsonb_array_elements(definition->'sections') WHERE value ? 'repeat' LOOP
  row_key:=section->'repeat'->>'key';
  IF jsonb_array_length(p_payload->row_key)<(section->'repeat'->>'minimumRows')::integer OR jsonb_array_length(p_payload->row_key)>60 THEN RAISE EXCEPTION 'Invalid number of rows: %',row_key USING ERRCODE='23514'; END IF;
  FOR row_value IN SELECT value FROM jsonb_array_elements(p_payload->row_key) LOOP
   IF jsonb_typeof(row_value)<>'object' THEN RAISE EXCEPTION 'Invalid row' USING ERRCODE='23514'; END IF;
   FOR unknown_key IN SELECT jsonb_object_keys(row_value) LOOP
    IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(section->'fields') f WHERE f->>'key'=unknown_key) THEN RAISE EXCEPTION 'Unknown row field: %',unknown_key USING ERRCODE='23514'; END IF;
   END LOOP;
   FOR field IN SELECT value FROM jsonb_array_elements(section->'fields') LOOP PERFORM private.assert_entergy_field(field,row_value->(field->>'key'),false); END LOOP;
   IF p_submit AND EXISTS(SELECT 1 FROM jsonb_each(row_value) x WHERE NOT(row_key='equipmentRows' AND x.key='operation') AND x.value NOT IN ('null'::jsonb,'[]'::jsonb,'""'::jsonb) AND (jsonb_typeof(x.value)<>'string' OR btrim(x.value#>>'{}')<>'')) THEN
    IF row_key='equipmentRows' AND (coalesce(row_value->>'operation','')='' OR coalesce(btrim(row_value->>'type'),'')='' AND coalesce(btrim(row_value->>'companyEquipmentNumber'),'')='') THEN RAISE EXCEPTION 'Used equipment rows need an operation and a type or equipment number' USING ERRCODE='23514'; END IF;
    IF row_key='customerRows' THEN FOREACH required_key IN ARRAY ARRAY['customerNameAddress','identifierTypes','identifier','oldDlocTransformer','newDlocTransformer'] LOOP
     IF row_value->required_key IS NULL OR row_value->required_key IN ('null'::jsonb,'[]'::jsonb,'""'::jsonb) OR (jsonb_typeof(row_value->required_key)='string' AND btrim(row_value->>required_key)='') THEN RAISE EXCEPTION 'Complete each used customer transfer row' USING ERRCODE='23514'; END IF;
    END LOOP; END IF;
   END IF;
  END LOOP;
 END LOOP;
 IF p_kind='cleanup' AND (jsonb_array_length(p_payload->'equipmentRows')>0 OR jsonb_array_length(p_payload->'customerRows')>0 OR jsonb_array_length(p_payload->'lightingMap')>0) THEN RAISE EXCEPTION 'Damage fields do not belong in a clean-up form' USING ERRCODE='23514'; END IF;
 IF p_kind='damage' AND p_submit AND coalesce(btrim(answers->>'fromDloc'),'')='' AND coalesce(btrim(answers->>'toDloc'),'')='' THEN RAISE EXCEPTION 'Record a From or To DLOC' USING ERRCODE='23514'; END IF;
 IF p_kind='damage' AND (coalesce(answers->>'latitude','')<>'')<>(coalesce(answers->>'longitude','')<>'') THEN RAISE EXCEPTION 'Record both GPS coordinates together' USING ERRCODE='23514'; END IF;
 IF jsonb_array_length(p_payload->'lightingMap')>100 THEN RAISE EXCEPTION 'Map is too large' USING ERRCODE='23514'; END IF;
 FOR stroke IN SELECT value FROM jsonb_array_elements(p_payload->'lightingMap') LOOP
  IF jsonb_typeof(stroke->'points') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Invalid map stroke' USING ERRCODE='23514'; END IF;
  IF jsonb_array_length(stroke->'points') NOT BETWEEN 2 AND 1000 THEN RAISE EXCEPTION 'Invalid map stroke length' USING ERRCODE='23514'; END IF;
  FOR point IN SELECT value FROM jsonb_array_elements(stroke->'points') LOOP
   IF jsonb_typeof(point)<>'array' THEN RAISE EXCEPTION 'Invalid map point' USING ERRCODE='23514'; END IF;
   IF jsonb_array_length(point)<>2 OR jsonb_typeof(point->0)<>'number' OR jsonb_typeof(point->1)<>'number' THEN RAISE EXCEPTION 'Invalid map coordinate' USING ERRCODE='23514'; END IF;
   IF (point->>0)::numeric NOT BETWEEN 0 AND 1000 OR (point->>1)::numeric NOT BETWEEN 0 AND 1000 THEN RAISE EXCEPTION 'Map coordinate out of bounds' USING ERRCODE='23514'; END IF;
  END LOOP;
 END LOOP;
 FOR unknown_key,damage_detail IN SELECT * FROM jsonb_each(p_payload->'damageReports') LOOP
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(definition->'sections') s WHERE s->>'id'=unknown_key) OR jsonb_typeof(damage_detail)<>'string' OR length(damage_detail#>>'{}')>2000 OR (p_submit AND btrim(damage_detail#>>'{}')='') THEN RAISE EXCEPTION 'Describe the reported section damage' USING ERRCODE='23514'; END IF;
 END LOOP;
END $$;
